let firstRoute=true,lastHash='';const AUTH_VIEWS=['login','register','forgot','reset'];
async function route(){clearTimeout(polling);justDrawn=-1;boardZoom=null;setMenu(false);const [view,id]=currentView();
 // Case pages are rendered on the server (for search engines); keep that markup instead of redrawing it.
 if(['cases','case'].includes(view)){if(root.dataset.ssr===view){markNav();if(firstRoute){firstRoute=false;track('page_view',view);if(view==='case'){track('case_open');initCasePage()}}const anchor=location.hash.length>1&&document.getElementById(location.hash.slice(1));if(anchor)anchor.scrollIntoView({block:'start'});return}location.reload();return}
 if(root.dataset.ssr)root.dataset.ssr='';
 const bz=state.settings.brand_zh,be=state.settings.brand_en,title=TITLES[view];document.title=title?`${t(...title)} · ${t(bz,be)}`:t(`${bz} · 在线塔罗占卜、AI塔罗解读与真人咨询`,`${be} · Online Tarot Readings, AI & Personal Consultations`);markNav();if(!firstRoute){window.scrollTo(0,0);root.focus({preventScroll:true})}firstRoute=false;track('page_view',view||'home');
 // Remember the page a visitor came from so signing in or up brings them straight back.
 if(['login','register'].includes(view)){if(lastHash)sess.set('returnTo',lastHash);else sess.del('returnTo')}else if(!AUTH_VIEWS.includes(view))lastHash=location.hash.slice(1)||view||'home';if(!state.installed)return setup();if(view==='forgot')return forgot();if(view==='reset')return resetPage(id);if(!view||view==='home')return home();if(['ai','human'].includes(view))return selectSpread(view);if(view==='question')return question(id);if(view==='read')return showRead(id);if(view==='book')return book(id);if(view==='login'||view==='register')return login(view);if(view==='history')return history();if(view==='admin')return admin();if(view==='contact')return contact();if(view==='learn')return learn();if(view==='terms')return terms();home()}
