async function copyText(v){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(v);return true}}catch(e){}
 // Plain-HTTP pages have no clipboard API: fall back to a temporary selection.
 const a=document.createElement('textarea');a.value=v;a.setAttribute('readonly','');a.className='copy-buffer';document.body.appendChild(a);a.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}a.remove();if(!ok)window.prompt(t('复制这个链接：','Copy this link:'),v);return ok}
