 if(list){wrap.removeAttribute('data-board');board.dataset.cls=board.className;board.className='cards card-list';board.removeAttribute('style');board.querySelectorAll('.tarot').forEach(el=>{el.removeAttribute('style');el.classList.remove('crossed')});wrap.querySelector('.board-zoom').removeAttribute('style')}
 else{wrap.setAttribute('data-board','');board.className=board.dataset.cls;board.querySelectorAll('.tarot').forEach(el=>{if(el.querySelector('.cross-pos'))el.classList.add('crossed')});boardZoom=null;layoutBoard()}
