function stripBlock(items){if(!items||!items.length)return '';return `<section class="cases-strip band" aria-labelledby="cases-title" data-strip-section aria-roledescription="carousel"><div class="section-head"><div><div class="eyebrow">READING EXAMPLES</div><h2 id="cases-title">${t('别人问了什么','What others asked')}</h2></div><div class="strip-controls"><button type="button" class="icon-btn" data-strip="prev" aria-label="${t('向前','Previous')}">←</button><button type="button" class="icon-btn" data-strip="toggle" aria-pressed="false" aria-label="${t('暂停自动滚动','Pause auto-scroll')}">❚❚</button><button type="button" class="icon-btn" data-strip="next" aria-label="${t('向后','Next')}">→</button><a href="/cases">${t('查看全部案例','All examples')} →</a></div></div><ul class="case-track" role="list">${items.map(caseCard).join('')}</ul><p class="case-note">${t('经用户授权、工作室审核后匿名展示。塔罗用于反思，不保证结果。','Shared with permission and reviewed by the studio. Tarot offers reflection, not guaranteed outcomes.')}</p></section>`}
// Slow auto-scroll for the example strip. It never moves while hovered, focused or touched,
// on touch screens, with reduced motion, or after the visitor presses pause (WCAG 2.2.2).
let stripFrame;
function initStrip(){cancelAnimationFrame(stripFrame);const sec=document.querySelector('[data-strip-section]');if(!sec)return;const lane=sec.querySelector('.case-track'),btn=sec.querySelector('[data-strip="toggle"]');
 const auto=wideScreen.matches&&matchMedia('(hover:hover) and (pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
 let paused=!auto,hold=false,last=0,pos=0,wait=0;
 const show=()=>{btn.setAttribute('aria-pressed',String(paused));btn.textContent=paused?'▶':'❚❚';btn.setAttribute('aria-label',paused?t('继续自动滚动','Resume auto-scroll'):t('暂停自动滚动','Pause auto-scroll'))};
 if(!auto)btn.hidden=true;show();
 btn.addEventListener('click',()=>{paused=!paused;show()});
 sec.querySelectorAll('[data-strip="prev"],[data-strip="next"]').forEach(b=>b.addEventListener('click',()=>{const w=(lane.querySelector('li')?.offsetWidth||280)+16;lane.scrollBy({left:b.dataset.strip==='next'?w:-w,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}));
 ['mouseenter','focusin','touchstart','pointerdown'].forEach(ev=>sec.addEventListener(ev,()=>hold=true,{passive:true}));['mouseleave','focusout'].forEach(ev=>sec.addEventListener(ev,()=>hold=false));
 if('IntersectionObserver' in window){const io=new IntersectionObserver(es=>{if(es.some(x=>x.isIntersecting)){track('case_strip_view');io.disconnect()}},{threshold:.4});io.observe(sec)}
 const step=ts=>{if(!document.body.contains(lane))return;const dt=last?Math.min(ts-last,64):0;last=ts;
  if(paused||hold||document.hidden){pos=lane.scrollLeft}else if(ts<wait){}else{const end=lane.scrollWidth-lane.clientWidth-1;pos+=dt*.028;if(pos>=end){wait=ts+2200;pos=0;lane.scrollTo({left:0,behavior:'smooth'})}else lane.scrollLeft=pos}
  stripFrame=requestAnimationFrame(step)};
 stripFrame=requestAnimationFrame(step)}
